def specialFilter(nums):
    def is_odd_first_digit(n):
        while n >= 10:
            n //= 10
        return n % 2 == 1

    def is_odd_last_digit(n):
        return n % 10 % 2 == 1

    count = 0
    for num in nums:
        if num > 10 and is_odd_first_digit(num) and is_odd_last_digit(num):
            count += 1
    return count

